        Application.UnitOfWork.setMock(uowMock);
    }

    private static void stubSelector(Set<Id> ids, List<Opportunity> opps) {
        mocks.startStubbing();
        mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selectorMock.selectById(ids)).thenReturn(opps);
        mocks.stopStubbing();
        Application.Selector.setMock(selectorMock);
