/**
 * Pushes newly created Accounts to the ERP as customers.
 *
 * The ticket asks to "make the callout right from the trigger" with one request
 * per account. A synchronous callout from a trigger is not allowed in Apex
 * (callouts are forbidden during the triggering DML transaction), so the work is
 * done asynchronously.
 *
 * One request per account is required so the ERP team can trace every account.
 *  - @future(callout=true) is capped at 50 per transaction, so a marketplace
 *    insert of 200 accounts would break it.
 *  - A self-chaining Queueable hits "Maximum stack depth" in tests and is fragile.
 *
 * Batch Apex with scope size 1 is the robust fit: each execute() runs in its own
 * transaction and makes exactly one callout, so 1..200 accounts each get their own
 * traceable request without hitting per-transaction callout or future limits.
 */
public with sharing class ErpCustomerSync implements Database.Batchable<SObject>, Database.AllowsCallouts {

    private final List<Id> accountIds;

    private ErpCustomerSync(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Entry point from the trigger. Collects the Ids and starts the batch job,
     * one callout per account (scope = 1).
     */
    public static void syncNewAccounts(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<Id> ids = new List<Id>();
        for (Account acc : newAccounts) {
            ids.add(acc.Id);
        }

        Database.executeBatch(new ErpCustomerSync(ids), 1);
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        return Database.getQueryLocator(
            [
                SELECT Id, Name, BillingCountry
                FROM Account
                WHERE Id IN :accountIds
                WITH USER_MODE
            ]
        );
    }

    public void execute(Database.BatchableContext context, List<Account> scope) {
        for (Account acc : scope) {
            sendCustomer(acc);
        }
    }

    public void finish(Database.BatchableContext context) {
        // Nothing to do. Error handling and retries are out of scope.
    }

    /**
     * Makes one POST per account. Body is a JSON array with a single element,
     * matching the ERP contract.
     */
    private void sendCustomer(Account acc) {
        List<Map<String, Object>> payload = new List<Map<String, Object>>();
        Map<String, Object> customer = new Map<String, Object>{
            'salesforceId' => acc.Id,
            'name' => acc.Name,
            'country' => String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry
        };
        payload.add(customer);

        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(payload, true));

        // Error handling and retries are explicitly out of scope for this ticket.
        new Http().send(req);
    }
}
```

