        insert primary;

        // Re-query to obtain the NPSP-created household account Id.
        primary = [
            SELECT Id, AccountId
            FROM Contact
            WHERE Id = :primary.Id
            LIMIT 1
        ];
        Id householdId = primary.AccountId;

        // Place any remaining members into that same household so NPSP
        // does not spin up additional households for them.
        if (members.size() > 1) {
            List<Contact> others = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact c = members[i];
                c.AccountId = householdId;
                others.add(c);
            }
            insert others;
        }

        // Ensure the first contact is the household's primary contact.
        update new Account(
            Id = householdId,
            npe01__One2OneContact__c = primary.Id
        );

        return householdId;
    }
}
