```apex
/**
 * Trigger action that keeps Account.FB_Open_Case_Count__c equal to the number of
 * the account's Cases where IsClosed = false.
 *
 * Registered via Trigger_Action__mdt for after insert, after update, after delete
 * and after undelete contexts on Case.
 *
 * Bulk-safe: at most one SOQL query (an aggregate count) and one DML statement per
 * trigger execution.
 */
public with sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {
    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerNew) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Case> newCases = (List<Case>) triggerNew;
        List<Case> oldCases = (List<Case>) triggerOld;
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < newCases.size(); i++) {
            Case newCase = newCases[i];
            Case oldCase = oldCases[i];
            Boolean accountChanged = newCase.AccountId != oldCase.AccountId;
            Boolean closedChanged = newCase.IsClosed != oldCase.IsClosed;
            if (accountChanged || closedChanged) {
                if (newCase.AccountId != null) {
                    accountIds.add(newCase.AccountId);
                }
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerOld) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerNew) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    /**
     * Recomputes FB_Open_Case_Count__c for the given set of accounts using one
     * aggregate SOQL query and one DML statement.
     */
    private void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Default every candidate account to 0 so accounts with no open cases are reset.
        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            openCountByAccountId.put(accountId, 0);
        }

        // One SOQL query: count open cases per account.
        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCountByAccountId.put((Id) ar.get('accId'), (Integer) ar.get('openCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : openCountByAccountId.keySet()) {
            accountsToUpdate.add(
                new Account(
                    Id = accountId,
                    FB_Open_Case_Count__c = openCountByAccountId.get(accountId)
                )
            );
        }

        // One DML statement.
        update accountsToUpdate;
    }
}
```

