/**
 * Singleton that caches the parent Accounts for the Contacts in the current
 * trigger execution, so that individual Trigger Actions do not query Accounts
 * themselves. Exactly one Account query is performed per trigger execution.
 *
 * The inner Service class is registered as the first before-insert Trigger
 * Action. It (re)loads accountsById on every trigger execution, because later
 * DML in the same transaction can involve other Accounts.
 */
public inherited sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {}

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Populate accountsById from the AccountIds referenced by the given
     * Contacts. Called by the Service trigger action.
     */
    private void loadAccounts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact con : contacts) {
            if (con.AccountId != null) {
                accountIds.add(con.AccountId);
            }
        }

        Map<Id, Account> freshMap = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            freshMap = new Map<Id, Account>(
                [
                    SELECT
                        Id,
                        BillingStreet,
                        BillingCity,
                        BillingPostalCode,
                        BillingCountry,
                        AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]
            );
        }
        this.accountsById = freshMap;
    }

    /**
     * First before-insert Trigger Action. Reloads the shared Account map on
     * every trigger execution.
     */
    public inherited sharing class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.getInstance().loadAccounts((List<Contact>) triggerNew);
        }
    }
}
