/**
 * Before-insert Trigger Action. When a new Contact has an Account and a blank
 * LeadSource, sets LeadSource to the Account's AccountSource. Contacts without
 * an Account, or with a LeadSource already set, are left alone.
 *
 * Uses the shared Account map from TA_Contact_Queries (no Account query here).
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (Contact con : (List<Contact>) triggerNew) {
            if (con.AccountId == null) {
                continue;
            }
            if (String.isNotBlank(con.LeadSource)) {
                continue;
            }
            Account acct = accountsById.get(con.AccountId);
            if (acct == null) {
                continue;
            }
            con.LeadSource = acct.AccountSource;
        }
    }
}
